        else if (c === ")" || c === "}") depth--
      } else if (c === "#" && isBoundary(code[j - 1])) {
        break
      } else if (c === ":") {
        let k = j + 1
        while (code[k] === ":") k++
        if (code[k] === "=") assignment(s, j, k + 1, end)
        else {
          text(s, j, "target")
          text(k, end, "text")
        }
        return
      } else if (c === "=") {
        const op = j > s && "+?!".includes(code[j - 1]!) ? j - 1 : j
        assignment(s, op, j + 1, end)
        return
      }
    }
    if (naming) {
      let e = s
      while (e < end && !isBlank(code[e]) && code[e] !== "#") e++
