        continue
      }
      if (MAKE_NAMING.has(word)) classify(e, end, true)
      else text(e, end, "text")
      return
    }
    classify(q, end, false)
  }

  let continued = false
  let recipe = false
  let i = 0
  while (i < n) {
    const nl = lineEnd(code, i)
    const end = trimCr(code, i, nl)
    if (continued) text(i, end, recipe ? "recipe" : "text")
    else if (code[i] === "\t") {
