    } else {
      recipe = false
      let p = i
      while (p < end && isBlank(code[p])) p++
      if (p < end) {
        if (code[p] === "#") push(spans, p, end, "comment")
        else line(p, end)
      }
    }
    continued = end > i && code[end - 1] === "\\"
    i = nl + 1
  }
  return spans
}

