      if (isSpace(c) || c === "=") {
        j++
        continue
      }
      if (c === '"' || c === "'") {
        j = quoted(j)
        continue
      }
      const attr = j
      while (j < n && !isAttrEnd(code[j]!)) j++
      push(spans, attr, j, "type")
      let k = j
      while (k < n && isSpace(code[k]!)) k++
      if (code[k] === "=") {
        k++
