    const nextSame: number[] = new Array<number>(starts.length).fill(-1)
    const last = new Map<number, number>()
    for (let r = starts.length - 1; r >= 0; r--) {
      nextSame[r] = last.get(lens[r]!) ?? -1
      last.set(lens[r]!, r)
    }
    const out: number[] = []
    for (let r = 0; r < starts.length; ) {
      const m = nextSame[r]!
      if (m === -1) r++
      else {
