    while (l < end && isBlank(code[l])) l++
    const lc = code[l]
    if (lc === "-" || lc === "*" || lc === "+") {
      if (l + 1 === end || isBlank(code[l + 1])) {
        push(spans, l, l + 1, "meta")
        return l + 1
      }
    } else if (isDigit(lc)) {
      let k = l
      while (k < end && k - l < 9 && isDigit(code[k])) k++
      if ((code[k] === "." || code[k] === ")") && (k + 1 === end || isBlank(code[k + 1]))) {
        push(spans, l, k + 1, "meta")
        return k + 1
      }
    }
