  const inline = (from: number, end: number): number => {
    const ranges = codeRanges(from, end)
    let rp = 0
    let bracket = false
    let j = from
    while (j < end) {
      while (rp < ranges.length && ranges[rp]! < j) rp += 2
      if (rp < ranges.length && ranges[rp] === j) {
